-- First create dummy workflows for templates
INSERT INTO workflows (id, owner_id, title, description, canvas_json, status, is_public, created_at, updated_at)
SELECT 
  ('550e8400-e29b-41d4-a716-446655' || LPAD(i::text, 6, '0'))::uuid,
  (SELECT id FROM users LIMIT 1),
  'Template Workflow ' || i,
  'Auto-generated workflow for template',
  '{}',
  'published',
  true,
  NOW(),
  NOW()
FROM generate_series(1, 10) as i
ON CONFLICT DO NOTHING;

